mapper.select:
SELECT bnum, m.userName , b_subject, b_hitCount, TO_CHAR(b_reg_date, 'YYYY-MM-DD') b_reg_date FROM board b JOIN member1 m ON b.memberIdx = m.memberIdx
AND b_Block = 0 AND b_type = #{b_type}
ORDER BY bnum DESC OFFSET #{offset} ROWS FETCH FIRST #{size} ROWS ONLY

SELECT bnum, b_subject FROM board b JOIN member1 m ON b.memberIdx = m.memberIdx
AND bnum > #{bnum} AND b_block = 0 AND b_type = #{b_type}
ORDER BY bnum ASC FETCH FIRST 1 ROWS ONLY

SELECT bnum, b_subject FROM board b JOIN member1 m ON b.memberIdx = m.memberIdx
AND bnum < #{bnum} AND b_block = 0 AND b_type = #{b_type}
ORDER BY bnum DESC FETCH FIRST 1 ROWS ONLY

SELECT COUNT(*)
FROM boardLike
WHERE bnum = #{bnum}

SELECT bnum, memberIdx
FROM boardLike
WHERE bnum = #{bnum} AND memberIdx = #{memberIdx}

